/**
 * Exo GEMM driver: mirrors PolyBench/C gemm.c but calls the Exo-generated kernel.
 */

#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <math.h>

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "gemm.h"

/* Include the Exo-generated kernel header. */
#include "generated/gemm/gemm.h"


/* Array initialization. */
static
void init_array(int ni, int nj, int nk,
		DATA_TYPE *alpha,
		DATA_TYPE *beta,
		DATA_TYPE POLYBENCH_2D(C,NI,NJ,ni,nj),
		DATA_TYPE POLYBENCH_2D(A,NI,NK,ni,nk),
		DATA_TYPE POLYBENCH_2D(B,NK,NJ,nk,nj))
{
  int i, j;

  *alpha = 1.5;
  *beta = 1.2;
  for (i = 0; i < ni; i++)
    for (j = 0; j < nj; j++)
      C[i][j] = (DATA_TYPE) ((i*j+1) % ni) / ni;
  for (i = 0; i < ni; i++)
    for (j = 0; j < nk; j++)
      A[i][j] = (DATA_TYPE) (i*(j+1) % nk) / nk;
  for (i = 0; i < nk; i++)
    for (j = 0; j < nj; j++)
      B[i][j] = (DATA_TYPE) (i*(j+2) % nj) / nj;
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int ni, int nj,
		 DATA_TYPE POLYBENCH_2D(C,NI,NJ,ni,nj))
{
  int i, j;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("C");
  for (i = 0; i < ni; i++)
    for (j = 0; j < nj; j++) {
	if ((i * ni + j) % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
	fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, C[i][j]);
    }
  POLYBENCH_DUMP_END("C");
  POLYBENCH_DUMP_FINISH;
}

/* Kernel implementation in Exo:
EXO START
from __future__ import annotations

from exo import *
from exo.API_scheduling import *
from exo.libs.memories import DRAM
from exo.stdlib.scheduling import *
from exo.stdlib.stdlib import *

@proc
def kernel_gemm(
    ni: size,
    nj: size,
    nk: size,
    alpha: DATA_TYPE,
    beta: DATA_TYPE,
    C: DATA_TYPE[ni, nj] @ DRAM,
    A: DATA_TYPE[ni, nk] @ DRAM,
    B: DATA_TYPE[nk, nj] @ DRAM,
):
    # Scale C by beta: C = beta * C
    for i in seq(0, ni):
        for j in seq(0, nj):
            C[i, j] = beta * C[i, j]

    # GEMM update: C += alpha * A * B
    #
    # Loop order (i, k, j) gives:
    #   - row-wise reuse of A[i, k] across all j,
    #   - row-wise, unit-stride access to B[k, j] and C[i, j]
    #     in the innermost j loop.
    for i in seq(0, ni):
        for k in seq(0, nk):
            for j in seq(0, nj):
                C[i, j] += alpha * A[i, k] * B[k, j]

# ---------------------------------------------------------------------------
# Scheduling: 3D blocking of the main GEMM loop nest.
#
# We keep the separate scaling loop as-is (it is simple and bandwidth-bound),
# and apply cache-friendly tiling only to the (i, k, j) compute nest.
#
# Tile sizes II, JJ, KK are compile-time tunables that can be adjusted
# for a particular machine's cache hierarchy. They do not change the
# mathematical result, only the execution order.
# ---------------------------------------------------------------------------

II = 64  # tile size in the i (row of A/C) dimension
JJ = 64  # tile size in the j (column of B/C) dimension
KK = 64  # tile size in the k (reduction) dimension

# Only the second `i` and `j` loops (the GEMM part) are transformed.
# There are two `i` loops and two `j` loops in the procedure:
#   - `i #0`, `j #0`: the scaling phase
#   - `i #1`, `j #1`: the GEMM phase
#
# 1. Split the GEMM `i` loop into (io, ii) tiles.
gemm_tiled = divide_loop(kernel_gemm, "i #1", II, ("io", "ii"))

# 2. Split the GEMM `j` loop into (jo, ji) tiles so that ji remains
#    the innermost loop with unit-stride access to rows of B and C.
gemm_tiled = divide_loop(gemm_tiled, "j #1", JJ, ("jo", "ji"))

# 3. Split the k loop into (ko, ki) tiles to improve reuse of A and B
#    within each (i, j) tile.
gemm_tiled = divide_loop(gemm_tiled, "k", KK, ("ko", "ki"))

# After the three splits, the GEMM compute nest (ignoring the separate
# scaling phase) has loop order:
#   io -> ii -> ko -> ki -> jo -> ji
#
# We now reorder these loops to:
#   io -> jo -> ko -> ii -> ki -> ji
#
# This gives:
#   - (io, jo, ko) as coarse-grain tiles over the whole matrices,
#   - (ii, ki, ji) as a compact inner micro-kernel, with ji innermost.
#
# Reordering is done locally on directly-nested loop pairs.

# Move `jo` just outside of `ki`.
gemm_tiled = reorder_loops(gemm_tiled, "ki jo")
# Then move `jo` outside of `ko`.
gemm_tiled = reorder_loops(gemm_tiled, "ko jo")
# Then move `jo` outside of `ii`, so we have io -> jo -> ii -> ko -> ki -> ji.
gemm_tiled = reorder_loops(gemm_tiled, "ii jo")
# Finally, swap `ii` and `ko` to get io -> jo -> ko -> ii -> ki -> ji.
gemm_tiled = reorder_loops(gemm_tiled, "ii ko")

# Simplify the resulting control structure (remove dead branches, fold
# simple expressions, etc.) to make the generated C code cleaner.
gemm_tiled = simplify(gemm_tiled)

# Use the tiled and reordered version as the exported kernel.
kernel_gemm = gemm_tiled
EXO END
*/


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int ni = NI;
  int nj = NJ;
  int nk = NK;

  /* Variable declaration/allocation. */
  DATA_TYPE alpha;
  DATA_TYPE beta;
  POLYBENCH_2D_ARRAY_DECL(C,DATA_TYPE,NI,NJ,ni,nj);
  POLYBENCH_2D_ARRAY_DECL(A,DATA_TYPE,NI,NK,ni,nk);
  POLYBENCH_2D_ARRAY_DECL(B,DATA_TYPE,NK,NJ,nk,nj);

  /* Initialize array(s). */
  init_array (ni, nj, nk, &alpha, &beta,
	      POLYBENCH_ARRAY(C),
	      POLYBENCH_ARRAY(A),
	      POLYBENCH_ARRAY(B));

  /* Start timer. */
  polybench_start_instruments;

  /* Run Exo kernel. Flatten 2D views to 1D pointers. */
  kernel_gemm (/*ctxt=*/NULL, ni, nj, nk,
	       (DATA_TYPE*)&alpha, (DATA_TYPE*)&beta,
	       (DATA_TYPE*)POLYBENCH_ARRAY(C),
	       (DATA_TYPE*)POLYBENCH_ARRAY(A),
	       (DATA_TYPE*)POLYBENCH_ARRAY(B));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(ni, nj,  POLYBENCH_ARRAY(C)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(C);
  POLYBENCH_FREE_ARRAY(A);
  POLYBENCH_FREE_ARRAY(B);

  return 0;
}

