from __future__ import annotations

from exo import *
from exo.API_scheduling import *
from exo.libs.memories import DRAM

# Base GEMM kernel that closely matches the original PolyBench
# implementation. We then derive an optimized version using
# Exo scheduling primitives.
@proc
def kernel_gemm_base(
    ni: size,
    nj: size,
    nk: size,
    alpha: DATA_TYPE,
    beta: DATA_TYPE,
    C: DATA_TYPE[ni, nj] @ DRAM,
    A: DATA_TYPE[ni, nk] @ DRAM,
    B: DATA_TYPE[nk, nj] @ DRAM,
):
    assert ni >= 0
    assert nj >= 0
    assert nk >= 0

    # Phase 1: scale C by beta.
    #   for (i0, j0): C[i0, j0] = beta * C[i0, j0]
    for i0 in seq(0, ni):
        for j0 in seq(0, nj):
            C[i0, j0] = beta * C[i0, j0]

    # Phase 2: C += alpha * A * B.
    #   for (i, k, j): C[i, j] += alpha * A[i, k] * B[k, j]
    # This layout corresponds to the reference PolyBench kernel.
    for i in seq(0, ni):
        for k in seq(0, nk):
            for j in seq(0, nj):
                C[i, j] += alpha * A[i, k] * B[k, j]


# ---------------------------------------------------------------------------
# Scheduling / optimization
# ---------------------------------------------------------------------------

# Tile sizes for the output matrix dimensions. These are compile-time
# constants that can be tuned for a specific cache hierarchy.
TI = 64  # tile size in the i (row) dimension
TJ = 64  # tile size in the j (column) dimension

# Start from the base kernel and create an optimized version named
# `kernel_gemm`, which is the symbol expected by the C driver.
kernel_gemm = rename(kernel_gemm_base, "kernel_gemm")

# 1) Block the `i` and `j` loops of the main GEMM computation to improve the
#    spatial and temporal locality of C, A, and B.
#
#    After these two transformations, the main triple loop (i, k, j) has
#    the structure:
#        for io
#          for ii
#            for k
#              for jo
#                for ji
#                  ...
#
#    The first (i0, j0) scaling nest uses different loop variables and is
#    unaffected by these transformations.
kernel_gemm = divide_loop(kernel_gemm, "i", TI, ["io", "ii"], tail="guard")
kernel_gemm = divide_loop(kernel_gemm, "j", TJ, ["jo", "ji"], tail="guard")

# 2) Reorder the tiled loops so that we compute one (TI x TJ) tile of C at a
#    time and, for each tile, stream across the shared-k dimension.
#
#    Target structure of the main computation:
#        for io
#          for jo
#            for k
#              for ii
#                for ji
#                  C[i, j] += alpha * A[i, k] * B[k, j]
#
#    where:
#        i = io * TI + ii
#        j = jo * TJ + ji
#
#    This ordering:
#      - Processes C in cache-friendly tiles.
#      - Reuses rows of A and rows of B across the entire tile.
#      - Keeps accesses to C[i, j] contiguous in memory in the innermost
#        (ii, ji) loops.
kernel_gemm = reorder_loops(kernel_gemm, "k jo")
kernel_gemm = reorder_loops(kernel_gemm, "ii jo")
kernel_gemm = reorder_loops(kernel_gemm, "ii k")

# 3) Simplify the resulting code to clean up guards and index expressions
#    introduced by tiling and reordering.
kernel_gemm = simplify(kernel_gemm)
EXO END
*/


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int ni = NI;
  int nj = NJ;
  int nk = NK;

  /* Variable declaration/allocation. */
  DATA_TYPE alpha;
  DATA_TYPE beta;
  POLYBENCH_2D_ARRAY_DECL(C,DATA_TYPE,NI,NJ,ni,nj);
  POLYBENCH_2D_ARRAY_DECL(A,DATA_TYPE,NI,NK,ni,nk);
  POLYBENCH_2D_ARRAY_DECL(B,DATA_TYPE,NK,NJ,nk,nj);

